mapper.select:
        select pra.player_id,pra.activity_id,pra.create_time,pra.round_index,pra.group_id,tfgr.content,tfgr.`level`
        from player_result_activityid${l} pra RIGHT JOIN t_free_game_result tfgr on  pra.activity_id = tfgr.activity_id
	    WHERE 1 = 1

            and player_id = #{playerId}


            and group_id = #{groupId}


            and group_id is null


            and DATE_FORMAT(create_time,'%Y-%m-%d') = #{dateStr}

	     order by create_time desc LIMIT ${pageIndex},${pageSize}

mapper.update:
UPDATE
    t_group_player
SET
    cost_pattern=#{costPattern},
    commission=#{commission},
    cost_user_type=#{costUserType}
WHERE
    group_id=#{groupId}
AND
    player_id=#{ower_id}

update t_group_player
set point_pool = point_pool + ${coins}
where group_id = #{groupId}

update t_group_player
set
    profit_count = profit_count +${profitCount},
    profit_club_count = profit_club_count + ${profitClubCount},
    point_pool = point_pool + ${pointPool}
where group_id = #{groupId}

update t_group_player set
    ower_id = #{assignor}
where group_id = #{groupId}
